#[allow(clippy::too_many_arguments)]
pub(crate) fn check_core_flow_arm<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, value: &Expr, on: &Ty, arm: &MatchArm, typed: &Ty, lendable: bool, through_the_reference: bool, mut_subject: Option<&str>, choice: i64, taken: i64, span: &Span) -> Option<Ty> {
    state.an_or_pattern_that_binds_unevenly(world, &arm.pattern, span);
    state.a_pattern_naming_a_member_a_type_does_not_have(world, &arm.pattern, span);
    state.a_pattern_inside_a_box(world, &arm.pattern, span);
    state.a_struct_pattern_that_leaves_fields_out(world, &arm.pattern, typed, span);
    check_core_flow_guard_box(state, world, host, &arm.pattern, &arm.body, (arm.guard).as_ref());
    let parts = check_core_flow_parts(state, world, &arm.pattern, typed, lendable);
    let a_list = check_core_flow_a_list(&arm.pattern);
    if typed.is_a_view() || through_the_reference || a_list { check_core_flow_copied_parts(state, world, arm, typed, through_the_reference); }
    let lent_parts = !lendable && typed.is_a_view();
    let mut owned_text: collections::BTreeSet<String> = collections::BTreeSet::new();
    if lent_parts { owned_text = check_core_flow_owned_texts(state, world, &arm.pattern, typed); }
    let frame = check_core_flow_frame(state, world, &arm.pattern, id_of(&arm.body) as i64, &parts, lent_parts, &owned_text);
    let mut in_place: collections::BTreeSet<i64> = collections::BTreeSet::new();
    for local in frame.iter() { if !state.copied(world, &local.ty) { in_place.insert(local.id); } }
    state.scope.push(frame);
    state.branch.push((choice, taken));
    let from = state.taken_so_far();
    let (_, handed_from) = state.taken_so_far();
    let changed_from = state.changed.len() as i64;
    check_core_flow_a_guard(state, world, host, &arm.pattern, (arm.guard).as_ref(), span);
    let ty = check_core_expr(state, world, host, &arm.body, span);
    let name = check_core_flow_variable(world, value);
    let by_reference = through_the_reference || a_list || name != "" && (on.is_a_view() || state.got_past_a_jump.contains(&name));
    check_core_flow_lent_parts(state, world, host, &arm.body, &parts, handed_from, changed_from, by_reference, a_list);
    let leaves = state.exits(world, &arm.body);
    state.a_branch_that_leaves(from, leaves, span);
    check_core_flow_changed_copies(state, &arm.body, changed_from, &in_place, mut_subject.is_some());
    if mut_subject.is_some() {
        state.parts_taken_out_of_a_mut_parameter(world, nikaia_std::index::or(mut_subject, || ""), &arm.body, typed, &parts, handed_from);
        check_core_flow_parts_handed_on_in_place(state, &arm.body, &in_place);
    }
    state.branch.pop();
    state.scope.pop();
    if state.leaves(world, &arm.body) { return None; }
    Some(ty)
}

