// this was written - see `contracts::sync`.
pub fn check_core_flow_match<H: CheckHost>(state: &mut CheckState, world: &CheckWorld<'_, '_, '_, '_, '_, '_, '_>, host: &H, expr: &Expr, value: &Expr, arms: &[MatchArm], span: &Span) -> Ty {
    let on = check_core_expr(state, world, host, value, span);
    let subject = check_core_flow_variable(world, value);
    if subject != "" {
        let bound = state.binding(&subject);
        if bound.is_some() {
            let id = nikaia_std::index::or(bound.as_ref().map(|__nikaia_it| __nikaia_it.id), || -1);
            if state.arm_bound.contains_key(&id) {
                let arm = nikaia_std::index::or(state.arm_bound.get(&id), || -1);
                state.facts.arm_subjects.insert(id_of(value) as i64, arm);
            }
        }
    }
    let several: Vec<Ty> = several_errors_of(&on);
    let mut typed = check_core_flow_caught(&state, world, &on, value);
    if !check_core_flow_unknown(&on) && !several.is_empty() { typed = Ty::Unknown; }
    let mut null_arm = false;
    for arm in arms.iter() { if check_core_flow_a_null_pattern(&arm.pattern) { null_arm = true; } }
    if null_arm { typed = check_core_flow_inside(&typed); }
    let lendable = state.an_owned_place(world, value, &typed);
    let mut_subject: Option<String> = state.a_mut_parameter_place(world, value);
    let a_variable = matches!(value, Expr::Variable(_, _));
    let through_the_reference = mut_subject.is_some() && a_variable;
    let through_a_view = check_core_flow_through_a_view(&state, world, value);
    let text = !typed.is_a_view() && check_core_flow_owned_text(&typed) && !shapes_has_a_null_arm(arms) && check_core_flow_text_arms(arms);
    if through_a_view && !typed.is_a_view() && state.takes_away(world, &typed) {
        state.facts.lent_scrutinees.insert(id_of(value) as i64);
        typed = view_of_type(&typed);
    }
    if text {
        state.facts.text_scrutinees.insert(id_of(value) as i64);
        if !typed.is_a_view() { typed = view_of_type(&typed); }
    }
    let lent_name = check_core_flow_a_lent_name(&state, world, value) || state.a_lent_let(world, value);
    if lent_name && !typed.is_a_view() && state.takes_away(world, &typed) { typed = view_of_type(&typed); }
    let outer_condition = state.stamped_condition;
    if on.is_seen() { state.stamped_condition = Some(span.start as i64); }
    let mut seen = Ty::Unknown;
    let mut any = false;
    let mut agree = true;
    let mut answered: Vec<CheckArm<'_>> = vec![];
    let choice = state.flow.next_choice;
    state.flow.next_choice += 1;
    let mut taken: i64 = 0;
    if state.discarded.contains(&(id_of(expr) as i64)) { for arm in arms.iter() { check_core_flow_arm_discarded(state, &arm.body); } }
    for arm in arms.iter() {
        let mut arm_typed = typed.clone();
        if !several.is_empty() { arm_typed = check_core_flow_member(world, &several, &arm.pattern); }
        let got = check_core_flow_arm(state, world, host, value, &on, arm, &arm_typed, lendable, through_the_reference, (mut_subject).as_deref(), choice, taken, span);
        taken += 1;
        if got.is_some() {
            let ty = nikaia_std::index::or(got, || Ty::Unknown);
            answered.push(CheckArm { tail: Some(&arm.body), ty: ty.clone() });
            state.arm_types.insert(id_of(check_peeled(&arm.body)) as i64, ty.clone());
            if !any {
                seen = ty;
                any = true;
            } else if seen != ty { agree = false; }
        }
    }
    state.stamped_condition = outer_condition;
    state.a_match_over_several_error_types(world, value, arms, span);
    let over = check_core_flow_caught(&state, world, &on, value);
    if !state.a_some_or_none_over_a_nullable(world, &over, value, arms, span) { state.a_match_that_misses_a_case(world, &over, arms, span); }
    state.a_variant_matched_on_a_nullable(world, &over, value, arms, span);
    state.a_null_arm_on_a_plain_value(world, &over, value, arms, span);
    let copied = match on {
        Ty::Nullable(ref inner) => { let inner = nikaia_std::boxed::open(inner); copies_as_a_view(inner) },
        _ => false,
    };
    if copied { state.facts.copied_walks.insert(id_of(value) as i64); }
    state.a_pattern_of_another_type(world, &over, value, arms, span);
    if any && agree { return seen; }
    check_core_flow_meet(state, world, expr, &answered, span)
}

pub(crate) fn check_core_flow_text_arms(arms: &[MatchArm]) -> bool {
    for arm in arms.iter() { if check_core_flow_text_pattern(&arm.pattern) { return true; } }
    false
}

pub(crate) fn check_core_flow_text_pattern(pattern: &MatchPattern) -> bool {
    match pattern {
        MatchPattern::Literal(literal) => { return matches!(literal, Expr::LitStr { .. }); },
        MatchPattern::Or(alternatives) => { for alternative in alternatives.iter() { if check_core_flow_text_pattern(alternative) { return true; } } },
        _ => { },
    }
    false
}

